<?php require_once __DIR__.'/includes/auth.php';require_user();$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);$s=$pdo->prepare("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='valid') registered_count FROM events e WHERE e.id=?");$s->execute([$eventId]);$ev=$s->fetch();if(!$ev){flash('danger','Event not found.');redirect('events.php');}if($_SERVER['REQUEST_METHOD']!=='POST'){if(!event_open($ev)){flash('warning','Registration is not open for this event.');redirect('event-details.php?id='.$eventId);} $pageTitle='Register for '.$ev['title'];require __DIR__.'/includes/header.php'; ?><section class="auth-wrap"><div class="auth-card"><span class="eyebrow">Reserve your spot</span><h1 class="h2 mt-3"><?=e($ev['title'])?></h1><p class="muted"><?=e(date('M j, Y',strtotime($ev['event_date'])))?> · <?=e($ev['venue'])?></p><p>Register as <strong><?=e($_SESSION['user_name'])?></strong> (<?=e($_SESSION['user_email'])?>).</p><form method="post" data-validate novalidate><?=csrf_field()?><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="form-check mb-4"><input class="form-check-input" type="checkbox" id="agree" name="agree" value="1" required data-msg-required="Please accept the event rules to continue."><label class="form-check-label" for="agree">I agree to follow the event rules and venue instructions.</label></div><button class="btn btn-primary w-100">Confirm registration</button><a class="btn btn-link w-100 mt-2" href="event-details.php?id=<?=$eventId?>">Cancel</a></form></div></section><?php require __DIR__.'/includes/footer.php';exit;}
verify_csrf();if(empty($_POST['agree'])){flash('danger','Please accept the event rules to continue.');redirect('registration.php?event_id='.$eventId);}try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM events WHERE id=? FOR UPDATE');$s->execute([$eventId]);$ev=$s->fetch();if(!$ev||$ev['status']!=='published')throw new RuntimeException('This event is not available for registration.');$now=date('Y-m-d H:i:s');if(($ev['registration_start']&&$ev['registration_start']>$now)||($ev['registration_end']&&$ev['registration_end']<$now)||strtotime($ev['event_date'])<strtotime('today'))throw new RuntimeException('The registration window for this event is closed.');$s=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='valid'");$s->execute([$eventId]);if((int)$s->fetchColumn()>=(int)$ev['capacity'])throw new RuntimeException('Sorry, this event has reached its capacity.');$s=$pdo->prepare("SELECT id FROM registrations WHERE user_id=? AND event_id=? AND status='valid'");$s->execute([$_SESSION['user_id'],$eventId]);if($s->fetch())throw new RuntimeException('You are already registered for this event. You can reopen your ticket from My Events.');$token=bin2hex(random_bytes(24));$entry='EE-'.strtoupper(bin2hex(random_bytes(4)));$rid='REG-'.strtoupper(bin2hex(random_bytes(5)));$s=$pdo->prepare("INSERT INTO registrations(user_id,event_id,registration_code,entry_code,qr_token,status) VALUES(?,?,?,?,?,'valid')");$s->execute([$_SESSION['user_id'],$eventId,$rid,$entry,$token]);$regId=(int)$pdo->lastInsertId();$pdo->commit();redirect('registration-success.php?id='.$regId);}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$ex instanceof PDOException?'Registration could not be completed. Please try again.':$ex->getMessage());redirect('event-details.php?id='.$eventId);}
